  OPEN: "Open",
  IN_PROGRESS: "In Progress",
  NEED_QUOTE: "Need to Quote",
  QUOTED: "Quoted",
  ALL_REPAIRED: "All Repaired",
  CALL_CUSTOMER: "All Repaired", // legacy name, shown as the new label
