// Mode toggle buttons
document.querySelectorAll("#mode-toggle button").forEach((b) =>
  b.addEventListener("click", () => setMode(b.dataset.mode))
);

// Manual entry
// Manual entry is a live AutoCount search, the same engine as Find Part:
// type a code or a description word, tap a suggestion to add it to the
// machine. Enter still adds an exact code directly, so a technician who
// knows the number (or uses a scanner gun) is not forced through the list.
let codeDebounce = null;
$("code-input").addEventListener("input", () => {
  clearTimeout(codeDebounce);
  const q = $("code-input").value.trim();
  const box = $("code-results");
  if (q.length < 2) { box.innerHTML = ""; return; }
  codeDebounce = setTimeout(async () => {
    try {
      const data = await api(`/api/parts-search?q=${encodeURIComponent(q)}`);
      const list = data.results || [];
      if (!list.length) {
        box.innerHTML = `<div class="fp-empty">No matching parts</div>`;
        return;
      }
      box.innerHTML = list.map((p) =>
        `<button type="button" class="company-option" data-code="${escapeAttr(p.item_code)}">
           <span class="fp-opt-desc">${escapeHtml(p.description)}${p.desc2 ? ` <span class="fp-opt-model">· ${escapeHtml(p.desc2)}</span>` : ""}</span>
           <span class="fp-opt-code mono">${escapeHtml(p.item_code)}</span>
         </button>`
      ).join("");
      box.querySelectorAll(".company-option").forEach((btn) =>
        btn.addEventListener("click", () => {
          addByCode(btn.dataset.code);
          $("code-input").value = "";
          box.innerHTML = "";
          $("code-input").focus();
        })
      );
    } catch (_) { box.innerHTML = ""; }
  }, 250);
});
$("code-input").addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    addByCode($("code-input").value);
    $("code-input").value = "";
    $("code-results").innerHTML = "";
  }
});

// QR restart
const _qrRst = $("qr-restart"); if (_qrRst) _qrRst.addEventListener("click", startQrScanner);

// Machine-parts list interactions (event delegation)
$("machine-parts").addEventListener("click", (e) => {
  // Pending (unsaved) part controls first
  const pdel = e.target.closest("[data-pdel]");
  const pinc = e.target.closest("[data-pinc]");
  const pdec = e.target.closest("[data-pdec]");
  if (pdel || pinc || pdec) {
    const el = pdel || pinc || pdec;
    const i = Number(el.dataset.pdel ?? el.dataset.pinc ?? el.dataset.pdec);
    const p = session.pendingParts[i];
    if (!p) return;
    if (pdel) session.pendingParts.splice(i, 1);
    else if (pinc) p.quantity += 1;
    else if (pdec) p.quantity = Math.max(1, p.quantity - 1);
    renderMachineParts();
    updateSlipFooter();
    return;
  }
  const del = e.target.closest("[data-del]");
  const inc = e.target.closest("[data-inc]");
  const dec = e.target.closest("[data-dec]");
  if (del) setPartQty(Number(del.dataset.del), 0);
  else if (inc) {
    const id = Number(inc.dataset.inc);
    const m = currentMachine();
    const p = m && m.parts.find((x) => x.id === id);
    if (p) setPartQty(id, p.quantity + 1);
  } else if (dec) {
    const id = Number(dec.dataset.dec);
    const m = currentMachine();
    const p = m && m.parts.find((x) => x.id === id);
    if (p) setPartQty(id, Math.max(0, p.quantity - 1));
  }
});
$("machine-parts").addEventListener("change", (e) => {
  if (e.target.dataset.pqty !== undefined) {
    const p = session.pendingParts[Number(e.target.dataset.pqty)];
    if (p) { p.quantity = Math.max(1, parseInt(e.target.value, 10) || 1); renderMachineParts(); updateSlipFooter(); }
  } else if (e.target.dataset.pprice !== undefined) {
    const p = session.pendingParts[Number(e.target.dataset.pprice)];
    if (p) { p.unit_price = Math.max(0, parseFloat(e.target.value) || 0); renderMachineParts(); updateSlipFooter(); }
  } else if (e.target.dataset.qty) {
    const q = Math.max(0, parseInt(e.target.value, 10) || 0);
    setPartQty(Number(e.target.dataset.qty), q);
  } else if (e.target.dataset.price) {
    const p = Math.max(0, parseFloat(e.target.value) || 0);
    setPartPrice(Number(e.target.dataset.price), p);
  }
});

